const popularEditions=popularEditionRows.map(([aliases,en,ko])=>({
  aliases,editions:[
    ...(en?[{provider:'webtoon-en',title:en[0],url:'/en/'+en[1]+'/list?title_no='+en[2],originalOnly:en[3]}]:[]),
    ...(ko?.[1]?[{provider:'naver',title:ko[0],url:NAVER+'/webtoon/list?titleId='+ko[1]}]:[]),
  ],
}));

function presentEdition(edition) {
  if(edition.externalUrl)return edition;
  return {...edition,platform:edition.platform||directoryProviders[edition.provider].name,
    externalUrl:edition.provider==='naver'?edition.url:edition.originalOnly?ORIGIN+edition.url:undefined};
}

function providerFor(url) {
  if (url.origin===DONGMAN) return 'dongman';
  if (url.pathname.startsWith('/fr/')) return 'webtoon-fr';
  return url.pathname.startsWith('/en/')?'webtoon-en':'webtoon';
}

function versionsOf(value,title='') {
  const url=new URL(value,ORIGIN);
  const provider=providerFor(url);
  const sameEdition=edition=>edition.provider===provider&&
    new URL(edition.url,ORIGIN).searchParams.get('title_no')===url.searchParams.get('title_no');
  const editions=[stellarEditions,traineeEditions,princessEditions].find(group=>group.some(sameEdition))||
    popularEditions.find(group=>group.editions.some(sameEdition)||group.aliases.includes(title))?.editions;
  return editions?.filter(edition=>edition.provider!==provider).map(presentEdition)??[];
}

