    for(const r of records){yield header(46,[[0,0x02014b50,4],[4,20,2],[6,20,2],[16,r.crc,4],[20,r.size,4],[24,r.size,4],[28,r.name.length,2],[42,r.offset,4]]);yield r.name;offset+=46+r.name.length}
